"""Find the stretches of opening hours nobody covers."""

from typing import List

from hourglass.models import Span
from hourglass.merging import merge_spans

def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"

def _label(begin: int, stop: int) -> str:
    return (
        f"gap {_clock(begin)}-{_clock(stop)} "
        f"({stop - begin} min)"
    )

def _inside(span: Span, opening: Span) -> bool:
    return (
        opening.start <= span.start
        and span.end <= opening.end
    )

def _check_inside(worked, opening) -> None:
    for span in worked:
        if not _inside(span, opening):
            raise ValueError(f"{span} is outside {opening}")

def _free_pairs(merged, opening):
    edges = [opening.start]
    for span in merged:
        edges += [span.start, span.end]
    edges.append(opening.end)
    return zip(edges[0::2], edges[1::2])

# ---
def find_gaps(worked, opening) -> List[str]:
    """One label per uncovered stretch of opening hours."""
    _check_inside(worked, opening)
    pairs = _free_pairs(merge_spans(worked), opening)
    return [
        _label(begin, stop)
        for begin, stop in pairs
        if begin < stop
    ]

